import { useState } from "react";
import { Container, Row, Col } from "react-bootstrap";
import contactImg from "../assets/img/im.webp";
import TrackVisibility from "react-on-screen";

export const Contact = () => {

  const formInitialDetails = {
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    message: "",
  };

  const [formDetails, setFormDetails] = useState(formInitialDetails);
  const [buttonText, setButtonText] = useState("Send Message");
  const [status, setStatus] = useState({});

  const onFormUpdate = (category, value) => {
    setFormDetails({
      ...formDetails,
      [category]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    setButtonText("Sending...");

    try {

      const formData = new FormData();

      formData.append("firstName", formDetails.firstName);
      formData.append("lastName", formDetails.lastName);
      formData.append("email", formDetails.email);
      formData.append("phone", formDetails.phone);
      formData.append("message", formDetails.message);

      formData.append("_subject", "New Contact Form Submission");
      formData.append("_captcha", "false");

      const response = await fetch(
        "https://formsubmit.co/20234848@fue.edu.eg",
        {
          method: "POST",
          body: formData,
        }
      );

      if (response.ok) {

        setStatus({
          success: true,
          message: "Message sent successfully!",
        });

        setFormDetails(formInitialDetails);

      } else {
        throw new Error("Failed to send");
      }

    } catch (error) {

      setStatus({
        success: false,
        message: "Something went wrong, please try again.",
      });

    }

    setButtonText("Send Message");
  };

  return (
    <section className="contact" id="connect">
      <Container>
        <Row className="align-items-center">

          <Col size={12} md={6}>
            <TrackVisibility>
              {({ isVisible }) => (
                <img
                  className={
                    isVisible
                      ? "animate__animated animate__zoomIn"
                      : ""
                  }
                  src={contactImg}
                  alt="Contact"
                />
              )}
            </TrackVisibility>
          </Col>

          <Col size={12} md={6}>
            <TrackVisibility>
              {({ isVisible }) => (
                <div
                  className={
                    isVisible
                      ? "animate__animated animate__fadeIn"
                      : ""
                  }
                >
 
                  <h2>Get In Touch</h2>

                  <form onSubmit={handleSubmit}>

                    <Row>

                      <Col sm={6} className="px-1">
                        <input
                          type="text"
                          value={formDetails.firstName}
                          placeholder="First Name"
                          onChange={(e) =>
                            onFormUpdate("firstName", e.target.value)
                          }
                          required
                        />
                      </Col>

                      <Col sm={6} className="px-1">
                        <input
                          type="text"
                          value={formDetails.lastName}
                          placeholder="Last Name"
                          onChange={(e) =>
                            onFormUpdate("lastName", e.target.value)
                          }
                          required
                        />
                      </Col>

                      <Col sm={6} className="px-1">
                        <input
                          type="email"
                          value={formDetails.email}
                          placeholder="Email Address"
                          onChange={(e) =>
                            onFormUpdate("email", e.target.value)
                          }
                          required
                        />
                      </Col>

                      <Col sm={6} className="px-1">
                        <input
                          type="tel"
                          value={formDetails.phone}
                          placeholder="Phone Number"
                          onChange={(e) =>
                            onFormUpdate("phone", e.target.value)
                          }
                        />
                      </Col>

                      <Col size={12} className="px-1">
                        <textarea
                          rows="6"
                          value={formDetails.message}
                          placeholder="Your Message"
                          onChange={(e) =>
                            onFormUpdate("message", e.target.value)
                          }
                          required
                        />

                        <button type="submit">
                          <span>{buttonText}</span>
                        </button>

                      </Col>

                      {status.message && (
                        <Col>
                          <p
                            className={
                              status.success === false
                                ? "danger"
                                : "success"
                            }
                          >
                            {status.message}
                          </p>
                        </Col>
                      )}

                    </Row>

                  </form>

                </div>
              )}
            </TrackVisibility>
          </Col>

        </Row>
      </Container>
    </section>
  );
};